"Каждый осколок Алатыря, найденный любым Ловчим, — в разломах и у хранителей-старейшин Капищ, — ложится в общий камень Ордена. Собрана грань — дорога в её мир распутана: {0} дня духи этой мифологии встречаются в {1} раза чаще, у всех Ловчих разом. Собраны все грани сезона — приходит Кощей: {2} дней он ждёт во всех Разломах мира, а потом раскалывает камень. Из трещины выходит новая мифология, начинается новый сезон — и в Лиге тоже. В новом сезоне у камня на одну грань больше.":"Cada fragmento de Alatyr que encuentra cualquier Cazador —en las grietas y con los guardianes ancianos de los Kapishche— va a la piedra común de la Orden. Cuando se reúne una cara, el camino a su mundo se desenreda: durante {0} días los espíritus de esa mitología aparecen {1} veces más, para todos los Cazadores a la vez. Cuando se reúnen todas las caras de la temporada, llega Koschei: durante {2} días espera en todas las Grietas del mundo y luego parte la piedra. De la grieta sale una nueva mitología y empieza una nueva temporada, también en la Liga. En la nueva temporada la piedra tiene una cara más.",
