"Европа":"Europa",
"Здесь сходятся старые дороги Нави, Олимпа, Асгарда и холмов сидов — от Москвы до Дублина.":"Aquí se cruzan los viejos caminos de Nav, el Olimpo, Asgard y las colinas de los sídhe, de Moscú a Dublín.",
"Азия":"Asia",
"От Уральских гор до Тихого океана. Отсюда родом небесные драконы Китая, а Сибирь и Средняя Азия — края славянских духов.":"De los montes Urales al océano Pacífico. De aquí vienen los dragones celestiales de China, y Siberia y Asia Central son tierras de espíritus eslavos.",
"Африка":"África",
"Здесь, у Нила, стоят врата Дуата — родины египетских богов и духов пустыни.":"Aquí, junto al Nilo, se alzan las puertas de la Duat, hogar de los dioses egipcios y de los espíritus del desierto.",
"Северная Америка":"América del Norte",
"Земля пернатых змеев: из долины Мехико вышли ацтекские боги и духи.":"Tierra de serpientes emplumadas: del valle de México salieron los dioses y espíritus aztecas.",
"Южная Америка":"América del Sur",
"Сельва, Анды и Амазонка. Ацтекские духи разлетелись и сюда — до самой Огненной Земли.":"Selva, los Andes y el Amazonas. Los espíritus aztecas también volaron hasta aquí, hasta la mismísima Tierra del Fuego.",
"Австралия и Океания":"Australia y Oceanía",
"Своих мифологий у Ордена здесь пока нет: все духи Австралии и Океании — гости, которых занесла Перепутица.":"La Orden aún no tiene mitologías propias aquí: todos los espíritus de Australia y Oceanía son huéspedes traídos por la Gran Maraña.",
"Антарктида":"Antártida",
"Здесь только пингвины и ледяные духи. Врата сюда не открываются — слишком холодно даже для Ловчих.":"Aquí solo hay pingüinos y espíritus de hielo. Las Puertas no se abren hacia aquí: hace demasiado frío incluso para los Cazadores.",
"Миров духов всегда было много — у каждого народа свой: Навь у славян, царство Аида у греков, Асгард у скандинавов, холмы сидов у кельтов, Дуат у египтян, Небеса у китайцев, Миктлан у ацтеков. На местах их держал <b>Алатырь</b> — бел-горюч камень в середине всех миров. Каждые врата вели в свою землю, и духи не путали дорог.":"Siempre hubo muchos mundos de espíritus, y cada pueblo tenía el suyo: Nav para los eslavos, el reino del Hades para los griegos, Asgard para los escandinavos, las colinas de los sídhe para los celtas, la Duat para los egipcios, los Cielos para los chinos, el Mictlán para los aztecas. Los mantenía en su sitio <b>Alatyr</b>, la piedra blanca ardiente del centro de todos los mundos. Cada puerta llevaba a su propia tierra, y los espíritus no se equivocaban de camino.",
"Однажды осенней ночью Кощей Бессмертный решил спрятать свою смерть понадёжнее — прямо в сердце Алатыря. Камень треснул и раскололся. Все врата распахнулись разом, дороги между мирами спутались в клубок, и духи и боги семи мифологий высыпали в наш мир — кто куда. Эту ночь назвали <b>Перепутицей</b>. Кощей уверяет, что камень треснул сам, но Локи и Сунь Укун при этих словах почему-то хихикают.":"Una noche de otoño, Koschei el Inmortal decidió esconder su muerte en un lugar más seguro: justo en el corazón de Alatyr. La piedra se agrietó y se partió. Todas las puertas se abrieron de golpe, los caminos entre los mundos se enredaron como un ovillo, y los espíritus y dioses de siete mitologías se desparramaron por nuestro mundo, cada uno por su lado. A esa noche la llamaron <b>la Gran Maraña</b>. Koschei asegura que la piedra se rompió sola, pero Loki y Sun Wukong, quién sabe por qué, se ríen por lo bajo cuando lo dice.",
"Теперь Гиппокамп плещется в московском фонтане, Леший гуляет по токийскому парку, а Ниссе греет котов в подъездах Каира. Любого духа можно встретить в любом уголке земли. Разломы — трещины от расколотого камня — открываются в каждом городе, а боги ставят святилища там, где осели: Капище по соседству с Пагодой, Храм через улицу от Пирамиды. Город рождает и своих, новых духов: Вайфайку, Трамвайника, Фонарника.":"Ahora un Hipocampo chapotea en una fuente de Moscú, un Leshy pasea por un parque de Tokio y un Nisse calienta gatos en los portales de El Cairo. Cualquier espíritu puede aparecer en cualquier rincón de la Tierra. Las grietas —fisuras que dejó la piedra rota— se abren en todas las ciudades, y los dioses levantan santuarios allí donde se asentaron: un Kapishche junto a una Pagoda, un Templo enfrente de una Pirámide. La ciudad también da a luz a sus propios espíritus nuevos: Vayfayka, Tramvaynik, Fonarnik.",
"Первыми с гостями поладили не учёные, а бабушки со своими оберегами: оказалось, оберег, сделанный с заботой, успокаивает любого духа, откуда бы тот ни был. Так появился <b>Орден Оберега</b> — союз Ловчих всех земель. Твоя задача — находить духов, ловить их оберегами, черпать силу из источников, закрывать разломы и собирать осколки Алатыря. Кто знает — может, однажды их хватит, чтобы распутать дороги домой.":"Los primeros en llevarse bien con los recién llegados no fueron los científicos, sino las abuelas con sus talismanes: resultó que un talismán hecho con cariño calma a cualquier espíritu, venga de donde venga. Así nació la <b>Orden del Talismán</b>, una unión de Cazadores de todas las tierras. Tu tarea: encontrar espíritus, atraparlos con talismanes, sacar fuerzas de las fuentes, cerrar grietas y reunir fragmentos de Alatyr. Quién sabe: quizá algún día basten para desenredar los caminos a casa.",
"Ясно":"Despejado",
"Переменная облачность":"Parcialmente nublado",
