"Первый дух":"El primer espíritu",
"Твои духи":"Tus espíritus",
"Рядом появился дух — видишь светящийся круг на карте? <b>Коснись духа</b>, а потом <b>смахни оберег вверх</b>, прямо в него.":"Ha aparecido un espíritu cerca: ¿ves el círculo brillante en el mapa? <b>Toca el espíritu</b> y luego <b>desliza el talismán hacia arriba</b>, directo hacia él.",
"Второй учебный дух рядом. Кольцо вокруг духа сжимается: бросай, когда оно <b>маленькое</b>, — выйдет «Отлично!». Зелёное кольцо — дух покладистый, красное — упрямый.":"El segundo espíritu de práctica está cerca. El anillo alrededor del espíritu se encoge: lanza cuando sea <b>pequeño</b> y saldrá «¡Genial!». Anillo verde: espíritu dócil; rojo: terco.",
"Это меню — здесь все разделы. Пока открыто не всё: разделы откроются по ходу обучения, подсвеченный — следующий.":"Este es el menú: aquí están todas las secciones. Aún no todo está abierto: las secciones se abrirán durante el tutorial; la resaltada es la siguiente.",
"Каждый пойманный дух — твой. Открой <b>меню</b> — золотой оберег внизу экрана.":"Cada espíritu que atrapas es tuyo. Abre el <b>menú</b>: el talismán dorado abajo de la pantalla.",
"Это твоя коллекция — все пойманные духи. Сверху — сортировка по силе, новизне и имени и фильтр по стихиям.":"Esta es tu colección: todos los espíritus que atrapaste. Arriba puedes ordenar por poder, novedad y nombre, y filtrar por elemento.",
"Это разделы Ордена. Открой <b>«Духи»</b> — там твоя коллекция.":"Estas son las secciones de la Orden. Abre <b>«Espíritus»</b>: ahí está tu colección.",
"Это карточка духа: сила, стихия, приёмы и семейство. Ниже — кнопки «Усилить» и «Превратить», а ещё можно сделать духа спутником.":"Esta es la ficha del espíritu: poder, elemento, técnicas y familia. Debajo están los botones «Potenciar» y «Evolucionar», y también puedes hacerlo tu compañero.",
"Коснись любого духа, чтобы открыть его <b>карточку</b>.":"Toca cualquier espíritu para abrir su <b>ficha</b>.",
"На карточке — сила духа. Нажми <b>«Усилить»</b>: за искры и эссенцию дух станет сильнее. Эссенцию приносят поимки духов того же семейства.":"En la ficha está el poder del espíritu. Pulsa <b>«Potenciar»</b>: con chispas y esencia el espíritu se hará más fuerte. La esencia se obtiene capturando espíritus de la misma familia.",
"Бестиарий — все виды духов. Пойманные видны целиком, встреченные — тенью. Коснись вида, чтобы прочитать о нём.":"El bestiario tiene todas las especies de espíritus. Las capturadas se ven completas; las vistas, como sombra. Toca una especie para leer sobre ella.",
"Теперь загляни в <b>«Бестиарий»</b> (меню) — там все виды духов. Сколько найдёшь ты?":"Ahora echa un vistazo al <b>«Bestiario»</b> (menú): ahí están todas las especies. ¿Cuántas encontrarás?",
"Обереги пополняют <b>источники</b> — светящиеся чаши у памятников, фонтанов и храмов. Дойди до ближайшего джойстиком по <b>стрелке вверху</b> и коснись его. Если рядом нет — прогуляйся по карте.":"Los talismanes se reponen en las <b>fuentes</b>: cuencos luminosos junto a monumentos, fuentes ornamentales y templos. Ve a la más cercana con el joystick siguiendo la <b>flecha de arriba</b> y tócala. Si no hay ninguna cerca, date una vuelta por el mapa.",
"Сумка: обереги, мёд, живая вода и ладан. Сверху видно, сколько ещё поместится; лишнее можно выбросить.":"Bolsa: talismanes, miel, Zhivaya Voda e incienso. Arriba se ve cuánto cabe todavía; lo que sobre puedes tirarlo.",
"Добыча уже в <b>Сумке</b>. Открой меню → «Сумка» и посмотри, что у тебя есть.":"El botín ya está en la <b>Bolsa</b>. Abre menú → «Bolsa» y mira lo que tienes.",
"Коконы греются шагами — одновременно можно греть три. Готовый кокон вылупится одним касанием. А твой первый дух идёт рядом — это спутник: в пути он находит эссенцию.":"Los capullos se incuban con tus pasos; puedes incubar tres a la vez. Un capullo listo eclosiona con un toque. Y tu primer espíritu camina a tu lado: es tu compañero y encuentra esencia por el camino.",
"Открой меню → <b>«Коконы»</b>. Первый кокон уже греется — пройди 2 км, и он вылупится.":"Abre menú → <b>«Capullos»</b>. El primer capullo ya se está incubando: camina 2 km y eclosionará.",
"Здесь задания дня — они обновляются в полночь. А источники иногда дают поручения: выполнишь — встретишь особого духа.":"Aquí están las misiones del día: se renuevan a medianoche. Y las fuentes a veces dan encargos: cúmplelos y encontrarás un espíritu especial.",
"Открой <b>«Задания»</b> — там задания дня.":"Abre <b>«Misiones»</b>: ahí están las misiones del día.",
"Путь Ловчего: что откроется на каждом уровне и какие награды ждут. Звания растут: Послушник, Ловчий, Следопыт, Ведун, Хранитель.":"La Senda del Cazador: qué se desbloquea en cada nivel y qué recompensas te esperan. Los títulos suben: Novicio, Cazador, Rastreador, Vidente, Guardián.",
"И последнее: открой <b>«Путь»</b> в меню — там видно, что откроется на каждом уровне Ловчего.":"Y por último: abre <b>«Senda»</b> en el menú: ahí ves qué se desbloquea en cada nivel de Cazador.",
