"«Достойно, Ловчий», — {0} склоняет голову. Капище «{1}» освящено тобой до конца дня.":"«Bien luchado, Cazador», {0} inclina la cabeza. Has consagrado el Kapishche «{1}» hasta el final del día.",
"Победа!":"¡Victoria!",
