"Лови духов вместе со мной в «Духолове»! Открой ссылку — мы сразу станем друзьями, а тебе достанется стартовый подарок:\n{0}":"¡Atrapa espíritus conmigo en «Dukholov»! Abre el enlace: seremos amigos al instante y recibirás un regalo de bienvenida:\\n{0}",
