"Рейтинг зависит от соперника: победа над сильным даёт много, над слабым — мало; поражение от слабого стоит дороже. В твоей лиге победа над равным — +{0}, поражение — −{1}; чем выше лига, тем медленнее подъём. Из лиги можно выпасть. Награду за лигу дают один раз за сезон. В начале нового сезона рейтинг сверх {2} срезается наполовину, а за высшую лигу прошлого сезона Орден дарит сундук. В лигах «{3}», «{4}» и «{5}» — ещё и амулет.":"La puntuación depende del rival: vencer a uno fuerte da mucho; a uno débil, poco; perder contra uno débil cuesta más. En tu liga, vencer a un igual da +{0} y perder, −{1}; cuanto más alta la liga, más lento se sube. Puedes bajar de liga. La recompensa de cada liga se da una vez por temporada. Al empezar una nueva temporada, la puntuación por encima de {2} se reduce a la mitad, y por la liga más alta de la temporada anterior la Orden regala un cofre. En las ligas «{3}», «{4}» y «{5}», además, un amuleto.",
